window.kbPageData["views/entry/k-288ffb6436d9291e"] = {"key":"entry/k-288ffb6436d9291e","state":{"route":"entry/k-288ffb6436d9291e"},"node":{"id":"k-288ffb6436d9291e","mode":"k","title":"无权处分与买卖合同效力","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["无权处分本身不影响房屋买卖合同效力"],"qs":["国考 2024 行政执法 行测#14"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"出卖人欠缺处分权这一事实本身不导致买卖合同无效。合同效力与标的物所有权能否转移，应分别判断。","review":{"definition":"出卖人欠缺处分权这一事实本身不导致买卖合同无效。合同效力与标的物所有权能否转移，应分别判断。","explanation":"老张是房屋所有权人，小张出售房屋属于无权处分。按题解采用的小张与小王订立合同的前提，不能仅凭小张无权处分、伪造手续就采纳A项的无效结论。B、C两项都认可合同有效，二者的区别在于小王能否因善意取得而获得房屋所有权。","references":[],"evidence":"无权处分并不影响房屋买卖合同的效力","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 行政执法 行测#14":{"paper":"国考 2024 行政执法 行测","n":14,"mod":"常识判断","src":["dfddc59dc6e7d9da5d71.pdf",3],"asrc":["6493f3a6a55c38431852.pdf",5],"card":"373d3c8b70e80f36d9d3207c","links":[{"id":"k-288ffb6436d9291e","role":"直接考查","why":"处分人欠缺处分权这一事实本身不足以否定买卖合同效力。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-288ffb6436d9291e":[["国考 2024 行政执法 行测#14"]]}};
